//! Editable application entry points included with every generated SDK.

/// The text of `src/main.rs`.
///
/// Cargo builds this file as the external executable. `lib.rs` also includes it
/// as a module, which puts the Windows DLL entry point in the `cdylib`. Both
/// modes call the same `run` function with a different memory reader.
pub(crate) fn main_source(crate_name: &str) -> String {
    const TEMPLATE: &str = r#"//! Application scaffold generated by ufathom. This file is yours to edit.
//!
//! The DLL and the external executable both call `run`. Generated files are
//! refreshed by later dumps, but an existing `main.rs` is preserved.

use ufathom_runtime::{mem::ProcessMemory, MemoryReader};
use ufathom_sdk as sdk;

/// Runs with checked, read-only access to the target's memory.
///
/// Add application logic here. `sdk::session` gives names, object paths,
/// `find_object`, `objects_of::<T>()`, `is_a`, `cast`, `static_class::<T>()`,
/// `default_object::<T>()`, `gworld()` and `gengine()`. Read fields of
/// generated types such as `sdk::core_uobject::UObject` with
/// `session.object(ptr).get(...)`.
///
/// Calling game functions needs the `inproc` feature and the game thread:
/// `let exec = unsafe { sdk::attach() }?;` then pass `&exec` to a generated
/// wrapper. The DLL worker below is not the game thread.
pub(crate) fn run(memory: &dyn MemoryReader) -> Result<(), Box<dyn std::error::Error>> {
    let session = sdk::session(memory)?;
    // Replace this with your own logic.
    let _objects = session.num_objects()?;
    if let Ok(Some(world)) = session.gworld() {
        let _world = session.full_name_of(world)?;
    }
    Ok(())
}

fn external_main() -> Result<(), Box<dyn std::error::Error>> {
    let Some(pid) = std::env::args().nth(1) else {
        return Err("usage: ufathom-sdk <PID>".into());
    };
    let pid: u32 = pid.parse()?;
    let memory = ProcessMemory::open(pid)?;
    run(&memory)?;
    Ok(())
}

fn main() {
    if let Err(error) = external_main() {
        eprintln!("{error}");
        std::process::exit(1);
    }
}
"#;
    TEMPLATE
        .replace("ufathom_sdk", &crate_name.replace('-', "_"))
        .replace("ufathom-sdk <PID>", &format!("{crate_name}-external <PID>"))
}

/// The text of the Windows-only `src/dll.rs` library entry point.
///
/// Keeping this out of `main.rs` prevents the external executable from
/// exporting a second `DllMain` when it links the SDK as an rlib.
pub(crate) fn dll_source() -> &'static str {
    r#"use std::ffi::c_void;
use std::sync::atomic::{AtomicUsize, Ordering};

use ufathom_runtime::mem::SelfMemory;
use windows_sys::Win32::Foundation::{CloseHandle, HANDLE, HINSTANCE, HMODULE};
use windows_sys::Win32::System::Diagnostics::Debug::OutputDebugStringW;
use windows_sys::Win32::System::LibraryLoader::{
    DisableThreadLibraryCalls, GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS, GetModuleHandleExW,
};
use windows_sys::Win32::System::SystemServices::DLL_PROCESS_ATTACH;
use windows_sys::Win32::System::Threading::CreateThread;

use crate::app::run;

static WORKER_HANDLE: AtomicUsize = AtomicUsize::new(0);

/// Starts the application on a worker, outside the loader lock.
#[allow(non_snake_case)]
#[no_mangle]
pub extern "system" fn DllMain(
    module: HINSTANCE,
    reason: u32,
    _reserved: *mut c_void,
) -> i32 {
    if reason == DLL_PROCESS_ATTACH {
        // SAFETY: `module` is the handle supplied by the loader.
        unsafe { DisableThreadLibraryCalls(module) };
        // SAFETY: the entry point has the required signature and no
        // parameter is passed. The worker starts after DllMain returns.
        let handle = unsafe {
            CreateThread(
                std::ptr::null(),
                0,
                Some(worker_entry),
                std::ptr::null(),
                0,
                std::ptr::null_mut(),
            )
        };
        if handle.is_null() {
            return 0;
        }
        WORKER_HANDLE.store(handle as usize, Ordering::Release);
    }
    1
}

extern "system" fn worker_entry(_parameter: *mut c_void) -> u32 {
    let handle = WORKER_HANDLE.swap(0, Ordering::AcqRel);
    if handle != 0 {
        // SAFETY: this is the thread handle created by DllMain. Closing
        // the handle does not stop the running thread.
        unsafe { CloseHandle(handle as HANDLE) };
    }

    // Keep the module mapped while application code can run. This scaffold
    // is resident: it intentionally does not implement hot-unload.
    let mut own_module: HMODULE = std::ptr::null_mut();
    // SAFETY: FROM_ADDRESS interprets the worker's address as a module
    // address and writes a new reference to `own_module`.
    let pinned = unsafe {
        GetModuleHandleExW(
            GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS,
            worker_entry as *const () as *const u16,
            &mut own_module,
        )
    };
    if pinned == 0 {
        debug("ufathom SDK: could not pin the application module");
        return 0;
    }

    match std::panic::catch_unwind(|| {
        let memory = SelfMemory::new();
        run(&memory)
    }) {
        Ok(Ok(())) => {}
        Ok(Err(error)) => debug(&format!("ufathom SDK: {error}")),
        Err(_) => debug("ufathom SDK: application panicked"),
    }
    0
}

fn debug(message: &str) {
    let wide: Vec<u16> = message.encode_utf16().chain(Some(0)).collect();
    // SAFETY: `wide` is NUL-terminated and lives through the call.
    unsafe { OutputDebugStringW(wide.as_ptr()) };
}
"#
}

#[cfg(test)]
mod tests {
    use super::main_source;

    #[test]
    fn the_sdk_crate_name_is_a_rust_identifier() {
        let source = main_source("my-game-sdk");
        assert!(source.contains("use my_game_sdk as sdk;"));
        assert!(!source.contains("ufathom_sdk"));
    }
}
